{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { addrName, expandRange } from './addr.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

function cmpCodePoints(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpCodePoints(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(x) {
  if (x.t === 'n') return x
  if (x.t === 'b') return num(x.v ? 1 : 0)
  return err('#VALUE!')
}

function finite(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.active = new Set()
  }

  format(v) {
    if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
    if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
    return String(v.v)
  }

  get(name) {
    const cell = this.cells.get(name)
    if (!cell) return ZERO
    if (this.memo.has(name)) return this.memo.get(name)
    if (this.active.has(name)) return err('#CYCLE!')
    this.active.add(name)
    const r = this.compute(cell.content)
    this.active.delete(name)
    this.memo.set(name, r)
    return r
  }

  compute(content) {
    if (content[0] === '=') {
      const f = parseFormula(content.slice(1))
      if (!f || f.bad) return err('#ERR!')
      return this.ev(f.ast)
    }
    if (content === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  expand(n) {
    // list of values contributed by a range node
    if (!n.a || !n.b) return [err('#REF!')]
    return expandRange(n.a, n.b).map((a) => this.get(addrName(a)))
  }

  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.a ? this.get(addrName(n.a)) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const x = this.ev(n.e)
        if (x.t === 'e') return x
        const v = toNum(x)
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    const r = this.ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      switch (n.op) {
        case '=': return { t: 'b', v: c === 0 }
        case '<>': return { t: 'b', v: c !== 0 }
        case '<': return { t: 'b', v: c < 0 }
        case '<=': return { t: 'b', v: c <= 0 }
        case '>': return { t: 'b', v: c > 0 }
        default: return { t: 'b', v: c >= 0 }
      }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
