{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, addrName, colIndex } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)[0]
  const rest = line.slice(m.length).replace(/^[ \t]+/, '')
  const a = parseAddress(m)
  if (!a) fail(`line ${i + 1}: invalid cell address ${m}`)
  const name = addrName(a)
  if (cells.has(name)) fail(`line ${i + 1}: cell ${name} is declared twice`)
  cells.set(name, { addr: a, content: rest })
})

const sorted = [...cells.values()].sort(
  (x, y) => colIndex(x.addr.col) - colIndex(y.addr.col) || x.addr.row - y.addr.row,
)

let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) {
    const name = addrName(c.addr)
    out += `${name}=${sheet.format(sheet.get(name))}\n`
  }
} else {
  for (const c of sorted) {
    let s = `${addrName(c.addr)}:`
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        for (const d of ast.deps) s += ` ${addrName(d)}`
      }
    }
    out += s + '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/addr.js","content":"export function colIndex(col) {
  const a = col.charCodeAt(0) - 64
  if (col.length === 1) return a
  return 26 + (a - 1) * 26 + (col.charCodeAt(1) - 64)
}

export function colName(idx) {
  if (idx <= 26) return String.fromCharCode(64 + idx)
  const r = idx - 27
  return String.fromCharCode(65 + Math.floor(r / 26), 65 + (r % 26))
}

// Returns {col, row} (col upper-cased) or null when not addressable.
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: m[1].toUpperCase(), row }
}

export function addrName(a) {
  return `${a.col}${a.row}`
}

export function expandRange(a, b) {
  const c1 = colIndex(a.col)
  const c2 = colIndex(b.col)
  const [c0, c9] = c1 <= c2 ? [c1, c2] : [c2, c1]
  const [r0, r9] = a.row <= b.row ? [a.row, b.row] : [b.row, a.row]
  const res = []
  for (let c = c0; c <= c9; c++) {
    for (let r = r0; r <= r9; r++) res.push({ col: colName(c), row: r })
  }
  return res
}
"}

{"file_path":"src/parse.js","content":"import { parseAddress, expandRange, colIndex, addrName } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

// Returns {ast, deps} or null when the grammar rejects the body.
// ast.bad is set when a range sits somewhere other than a function argument.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let bad = false
  const deps = new Map()
  const fail = Symbol('fail')
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function addDep(a) { deps.set(addrName(a), a) }

  function expr() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) throw fail
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = expr()
      if (!isOp(')')) throw fail
      p++
      return { t: 'paren', e }
    }
    if (tk.k !== 'word') throw fail
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(expr())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      if (!isOp(')')) throw fail
      p++
      for (const a of args) if (a.t === 'range') a.direct = true
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      const t2 = peek()
      if (!t2 || t2.k !== 'word') throw fail
      p++
      const a = parseAddress(tk.v)
      const b = parseAddress(t2.v)
      if (a && b) for (const c of expandRange(a, b)) addDep(c)
      return { t: 'range', a, b, direct: false }
    }
    const u = tk.v.toUpperCase()
    if (u === 'TRUE') return { t: 'bool', v: true }
    if (u === 'FALSE') return { t: 'bool', v: false }
    const a = parseAddress(tk.v)
    if (a) addDep(a)
    return { t: 'ref', a }
  }

  let ast
  try {
    ast = expr()
    if (p !== toks.length) return null
  } catch (e) {
    if (e === fail) return null
    throw e
  }
  (function walk(n) {
    if (n.t === 'range' && !n.direct) bad = true
    if (n.t === 'bin') { walk(n.l); walk(n.r) }
    else if (n.t === 'un' || n.t === 'paren') walk(n.e)
    else if (n.t === 'call') n.args.forEach(walk)
  })(ast)
  const list = [...deps.values()].sort(
    (x, y) => colIndex(x.col) - colIndex(y.col) || x.row - y.row,
  )
  return { ast, bad, deps: list }
}
"}

