{"file_path":"src/addr.js","content":"export function colIndex(col) {
  const a = col.charCodeAt(0) - 64
  if (col.length === 1) return a
  return 26 + (a - 1) * 26 + (col.charCodeAt(1) - 64)
}

export function colName(idx) {
  if (idx <= 26) return String.fromCharCode(64 + idx)
  const r = idx - 27
  return String.fromCharCode(65 + Math.floor(r / 26), 65 + (r % 26))
}

// Returns {col, row} (col upper-cased) or null when not addressable.
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: m[1].toUpperCase(), row }
}

export function addrName(a) {
  return `${a.col}${a.row}`
}

export function expandRange(a, b) {
  const c1 = colIndex(a.col)
  const c2 = colIndex(b.col)
  const [c0, c9] = c1 <= c2 ? [c1, c2] : [c2, c1]
  const [r0, r9] = a.row <= b.row ? [a.row, b.row] : [b.row, a.row]
  const res = []
  for (let c = c0; c <= c9; c++) {
    for (let r = r0; r <= r9; r++) res.push({ col: colName(c), row: r })
  }
  return res
}
"}

{"file_path":"src/parse.js","content":"import { parseAddress, expandRange, colIndex, addrName } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

// Returns {ast, deps} or null when the grammar rejects the body.
// ast.bad is set when a range sits somewhere other than a function argument.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let bad = false
  const deps = new Map()
  const fail = Symbol('fail')
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function addDep(a) { deps.set(addrName(a), a) }

  function expr() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) throw fail
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = expr()
      if (!isOp(')')) throw fail
      p++
      return { t: 'paren', e }
    }
    if (tk.k !== 'word') throw fail
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(expr())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      if (!isOp(')')) throw fail
      p++
      for (const a of args) if (a.t === 'range') a.direct = true
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      const t2 = peek()
      if (!t2 || t2.k !== 'word') throw fail
      p++
      const a = parseAddress(tk.v)
      const b = parseAddress(t2.v)
      if (a && b) for (const c of expandRange(a, b)) addDep(c)
      return { t: 'range', a, b, direct: false }
    }
    const u = tk.v.toUpperCase()
    if (u === 'TRUE') return { t: 'bool', v: true }
    if (u === 'FALSE') return { t: 'bool', v: false }
    const a = parseAddress(tk.v)
    if (a) addDep(a)
    return { t: 'ref', a }
  }

  let ast
  try {
    ast = expr()
    if (p !== toks.length) return null
  } catch (e) {
    if (e === fail) return null
    throw e
  }
  (function walk(n) {
    if (n.t === 'range' && !n.direct) bad = true
    if (n.t === 'bin') { walk(n.l); walk(n.r) }
    else if (n.t === 'un' || n.t === 'paren') walk(n.e)
    else if (n.t === 'call') n.args.forEach(walk)
  })(ast)
  const list = [...deps.values()].sort(
    (x, y) => colIndex(x.col) - colIndex(y.col) || x.row - y.row,
  )
  return { ast, bad, deps: list }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { addrName, expandRange } from './addr.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

function cmpCodePoints(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpCodePoints(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(x) {
  if (x.t === 'n') return x
  if (x.t === 'b') return num(x.v ? 1 : 0)
  return err('#VALUE!')
}

function finite(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.active = new Set()
  }

  format(v) {
    if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
    if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
    return String(v.v)
  }

  get(name) {
    const cell = this.cells.get(name)
    if (!cell) return ZERO
    if (this.memo.has(name)) return this.memo.get(name)
    if (this.active.has(name)) return err('#CYCLE!')
    this.active.add(name)
    const r = this.compute(cell.content)
    this.active.delete(name)
    this.memo.set(name, r)
    return r
  }

  compute(content) {
    if (content[0] === '=') {
      const f = parseFormula(content.slice(1))
      if (!f || f.bad) return err('#ERR!')
      return this.ev(f.ast)
    }
    if (content === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  expand(n) {
    // list of values contributed by a range node
    if (!n.a || !n.b) return [err('#REF!')]
    return expandRange(n.a, n.b).map((a) => this.get(addrName(a)))
  }

  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.a ? this.get(addrName(n.a)) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const x = this.ev(n.e)
        if (x.t === 'e') return x
        const v = toNum(x)
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    const r = this.ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      switch (n.op) {
        case '=': return { t: 'b', v: c === 0 }
        case '<>': return { t: 'b', v: c !== 0 }
        case '<': return { t: 'b', v: c < 0 }
        case '<=': return { t: 'b', v: c <= 0 }
        case '>': return { t: 'b', v: c > 0 }
        default: return { t: 'b', v: c >= 0 }
      }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      default: return finite(Math.pow(a.v, b.v))
    }
  }

  values(args) {
    const out = []
    for (const a of args) {
      if (a.t === 'range') out.push(...this.expand(a))
      else out.push(this.ev(a))
    }
    return out
  }

  call(n) {
    const k = n.args.length
    const name = n.name
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const c = this.single(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.single(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (k !== 1) return err('#ERR!')
      const x = this.single(n.args[0])
      if (x.t === 'e') return x
      const v = toNum(x)
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (k < 1) return err('#ERR!')
    const vals = this.values(n.args)
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const c = toNum(v)
      if (c.t === 'e') return c
      nums.push(c.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      default: return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  single(a) {
    if (a.t !== 'range') return this.ev(a)
    const vals = this.expand(a)
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    return vals.length === 1 ? vals[0] : err('#VALUE!')
  }
}
"}

