import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, addrName, colIndex } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)[0]
  const rest = line.slice(m.length).replace(/^[ \t]+/, '')
  const a = parseAddress(m)
  if (!a) fail(`line ${i + 1}: invalid cell address ${m}`)
  const name = addrName(a)
  if (cells.has(name)) fail(`line ${i + 1}: cell ${name} is declared twice`)
  cells.set(name, { addr: a, content: rest })
})

const sorted = [...cells.values()].sort(
  (x, y) => colIndex(x.addr.col) - colIndex(y.addr.col) || x.addr.row - y.addr.row,
)

let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) {
    const name = addrName(c.addr)
    out += `${name}=${sheet.format(sheet.get(name))}\n`
  }
} else {
  for (const c of sorted) {
    let s = `${addrName(c.addr)}:`
    if (c.content[0] === '=') {
      const f = parseFormula(c.content.slice(1))
      if (f) for (const d of f.deps) s += ` ${addrName(d)}`
    }
    out += s + '\n'
  }
}
process.stdout.write(out)
